// POCKET-BRAIN service worker (generated by scripts/build-sw.mjs; do not edit dist/sw.js).
// Policy: cache-first for the precached app shell and for lazily loaded hashed assets; everything else goes
// straight to the network.
// Never touches cross-origin requests (Hugging Face model downloads) or api.github.com.
const VERSION = '__VERSION__';
const CACHE = 'pocket-brain-shell-' + VERSION;
// Not versioned: hashed file names never change content; the activate step keeps it.
const RUNTIME = 'pocket-brain-runtime';
const BASE = '__BASE__';
const PRECACHE = __PRECACHE__;
const PRECACHE_SET = new Set(PRECACHE);

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches
      .open(CACHE)
      .then((cache) => cache.addAll(PRECACHE.map((u) => new Request(u, { cache: 'reload' }))))
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) =>
        Promise.all(
          keys.filter((k) => k.startsWith('pocket-brain-shell-') && k !== CACHE).map((k) => caches.delete(k)),
        ),
      )
      .then(() => self.clients.claim()),
  );
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  // Cross-origin (huggingface.co, api.github.com, ...): do not intercept at all.
  if (url.origin !== self.location.origin) return;
  if (url.hostname === 'api.github.com') return;
  // Lazy chunks of the build (the local model code and wasm): file names carry a content hash, so once fetched
  // they are kept for offline use. The model shards themselves (BASE + 'model/') are cached by wllama, not here.
  if (url.pathname.startsWith(BASE + 'assets/') && !PRECACHE_SET.has(url.pathname)) {
    event.respondWith(
      caches.open(RUNTIME).then((cache) =>
        cache.match(url.pathname).then(
          (hit) =>
            hit ||
            fetch(req).then((res) => {
              // Kept alive until written (iOS may stop the worker early); 200 only (put() refuses a 206 partial).
              if (res.status === 200) event.waitUntil(cache.put(url.pathname, res.clone()).catch(() => undefined));
              return res;
            }),
        ),
      ),
    );
    return;
  }
  // Only the precached shell is served from cache; ignore the query string (e.g. ?t=...).
  if (!PRECACHE_SET.has(url.pathname)) return;
  event.respondWith(
    caches.open(CACHE).then((cache) =>
      cache.match(url.pathname).then((hit) => hit || fetch(req)),
    ),
  );
});
